using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace PublyApp.Api.Modules.Tenants.Entities;

public sealed class TenantStatusHistoryConfiguration
	: IEntityTypeConfiguration<TenantStatusHistory> {
	public void Configure(EntityTypeBuilder<TenantStatusHistory> builder) {
		// Rows are written by the tenants_record_status_history trigger, never
		// by EF, so the id has to be generated by the database (#2349).
		builder
			.Property(history => history.Id)
			.HasDefaultValueSql("uuidv7()");
	}
}
